'use strict';
const $=id=>document.getElementById(id), sub=['₀','₁','₂','₃','₄'];
const state={count:2,beta:[.5,1,-.5,.7,-.3],slices:[0,0,0,0],noise:.8,n:80,seed:17,view:'model',errors:false,yaw:-.65,pitch:.48,zoom:1};
const truth=[.7,1.65,-.9,.7,-.5]; let data=[];const canvas=$('graph'),ctx=canvas.getContext('2d');
function rng(seed){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function makeData(){const r=rng(state.seed);data=Array.from({length:state.n},()=>{const x=Array.from({length:4},()=>r()*6-3);let e=0;for(let k=0;k<6;k++)e+=r();e=(e-3)*Math.SQRT2;return{x,y:truth[0]+x.slice(0,state.count-1).reduce((sum,v,i)=>sum+v*truth[i+1],0)+e*state.noise};});}
function prediction(x,b=state.beta){return b[0]+x.slice(0,state.count-1).reduce((a,v,i)=>a+v*b[i+1],0);}
function mse(b=state.beta){return data.reduce((s,p)=>s+(prediction(p.x,b)-p.y)**2,0)/data.length;}
function solveFit(){const n=state.count,A=Array.from({length:n},()=>Array(n+1).fill(0));for(const p of data){const x=[1,...p.x.slice(0,n-1)];for(let i=0;i<n;i++){for(let j=0;j<n;j++)A[i][j]+=x[i]*x[j];A[i][n]+=x[i]*p.y;}}for(let i=0;i<n;i++){let pivot=i;for(let j=i+1;j<n;j++)if(Math.abs(A[j][i])>Math.abs(A[pivot][i]))pivot=j;[A[i],A[pivot]]=[A[pivot],A[i]];if(Math.abs(A[i][i])<1e-10)throw new Error('Please shuffle the data and try again.');const d=A[i][i];for(let k=i;k<=n;k++)A[i][k]/=d;for(let j=0;j<n;j++)if(j!==i){const f=A[j][i];for(let k=i;k<=n;k++)A[j][k]-=f*A[i][k];}}return A.map(row=>row[n]);}
function colorRange(input){input.style.setProperty('--fill',100*(+input.value-+input.min)/(+input.max-+input.min)+'%');}
function controls(){ $('coefficients').innerHTML=Array.from({length:state.count},(_,i)=>`<div class="slider-block"><div class="label-row"><label for="beta${i}" class="coefficient-name"><span class="coef-tag">β${sub[i]}</span> ${i===0?'Intercept':'Weight '+i}</label><output id="value${i}" for="beta${i}">${state.beta[i].toFixed(2)}</output></div><input id="beta${i}" type="range" min="-4" max="4" step="0.01" value="${state.beta[i]}"><div class="range-labels"><span>−4</span><span>+4</span></div></div>`).join('');for(let i=0;i<state.count;i++){const input=$('beta'+i);colorRange(input);input.oninput=()=>{state.beta[i]=+input.value;$('value'+i).value=state.beta[i].toFixed(2);colorRange(input);render();};}
 $('sliceControls').innerHTML=state.count>3?'<div class="slice-title">SLICE THROUGH EXTRA DIMENSIONS</div><p class="slice-hint">Hold these inputs fixed to see a 3D slice. Dots are adjusted to this slice.</p>'+Array.from({length:state.count-3},(_,j)=>{const i=j+2;return`<div class="slider-block"><div class="label-row"><label for="slice${i}">Hold x${sub[i+1]} at</label><output id="sliceVal${i}">${state.slices[i].toFixed(1)}</output></div><input id="slice${i}" type="range" min="-3" max="3" step="0.1" value="${state.slices[i]}"></div>`;}).join(''):'';for(let i=2;i<state.count-1;i++){const input=$('slice'+i);colorRange(input);input.oninput=()=>{state.slices[i]=+input.value;$('sliceVal'+i).value=state.slices[i].toFixed(1);colorRange(input);render();};}
 document.querySelectorAll('[data-count]').forEach(b=>{b.classList.toggle('selected',+b.dataset.count===state.count);b.setAttribute('aria-pressed',+b.dataset.count===state.count);});$('countHelp').textContent=state.count===2?'1 input + 1 intercept = a line in 2D.':state.count===3?'2 inputs + 1 intercept = a plane in 3D.':`${state.count-1} inputs + 1 intercept. Explore a 3D slice.`;
}
function line(points,color,width=1,dash=[]){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dash);ctx.stroke();ctx.setLineDash([]);}
function text(txt,x,y,color='#797483',size=11,align='center'){ctx.font=`${size}px "DM Sans",sans-serif`;ctx.fillStyle=color;ctx.textAlign=align;ctx.fillText(txt,x,y);}
function dot(p,r=4,color='#9078df'){ctx.beginPath();ctx.arc(...p,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.strokeStyle='#3a304f';ctx.lineWidth=1;ctx.stroke();}
function draw2D(w,h){const pad={l:54,r:27,t:51,b:47},plotW=w-pad.l-pad.r,plotH=h-pad.t-pad.b;const xLim=4/state.zoom,yLim=8/state.zoom;const p=(x,y)=>[pad.l+(x+xLim)/(2*xLim)*plotW,pad.t+(yLim-y)/(2*yLim)*plotH];ctx.save();ctx.beginPath();ctx.rect(pad.l,pad.t,plotW,plotH);ctx.clip();for(let x=-10;x<=10;x++)line([p(x,-yLim),p(x,yLim)],x===0?'#938d9e':'#e8e4ed',x===0?1.3:.8);for(let y=-20;y<=20;y+=2)line([p(-xLim,y),p(xLim,y)],y===0?'#938d9e':'#e8e4ed',y===0?1.3:.8);if(state.errors)for(const v of data)line([p(v.x[0],v.y),p(v.x[0],prediction(v.x))],'#db85998c',1,[3,3]);for(const v of data)dot(p(v.x[0],v.y),3.8);line([p(-xLim,state.beta[0]-state.beta[1]*xLim),p(xLim,state.beta[0]+state.beta[1]*xLim)],'#28232d',5);line([p(-xLim,state.beta[0]-state.beta[1]*xLim),p(xLim,state.beta[0]+state.beta[1]*xLim)],'#f4c537',3);ctx.restore();for(let x=Math.ceil(-xLim);x<=xLim;x++)text(x,...[p(x,0)[0],h-pad.b+18]);for(let y=Math.ceil(-yLim/2)*2;y<=yLim;y+=2)text(y,pad.l-13,p(0,y)[1]+4);text('Input x₁',pad.l+plotW/2,h-12,'#4c4558',12);ctx.save();ctx.translate(15,pad.t+plotH/2);ctx.rotate(-Math.PI/2);text('Output y',0,0,'#4c4558',12);ctx.restore();}
function conditionalMinimum(){const residual=data.map(p=>p.y-p.x.slice(1,state.count-1).reduce((a,v,i)=>a+v*state.beta[i+2],0));const meanX=data.reduce((a,p)=>a+p.x[0],0)/data.length,meanY=residual.reduce((a,v)=>a+v,0)/data.length;const b1=data.reduce((a,p,i)=>a+(p.x[0]-meanX)*(residual[i]-meanY),0)/data.reduce((a,p)=>a+(p.x[0]-meanX)**2,0);return[meanY-b1*meanX,b1];}
function draw3D(w,h){const loss=state.view==='loss',zLim=loss?Math.max(1,...[-4,4].flatMap(a=>[-4,4].map(b=>mse([a,b,...state.beta.slice(2)])))):16,scale=Math.min(w/14,h/9.5)*state.zoom,cy=Math.cos(state.yaw),sy=Math.sin(state.yaw),cp=Math.cos(state.pitch),sp=Math.sin(state.pitch);function project(x,y,z){const zz=loss?z/zLim*4.2-1.5:z/4,rx=x*cy-y*sy,ry=x*sy+y*cy;return[w/2+rx*scale,h*.59+(ry*sp-zz*cp)*scale];}function poly(points,fill,stroke){ctx.beginPath();points.map(v=>project(...v)).forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle=stroke;ctx.lineWidth=.6;ctx.stroke();}const base=loss?0:-12;for(let i=-4;i<=4;i++){line([project(i,-4,base),project(i,4,base)],'#d4cedd',.8);line([project(-4,i,base),project(4,i,base)],'#d4cedd',.8);}line([project(-4,-4,base),project(4,-4,base)],'#776d87',1.5);line([project(-4,-4,base),project(-4,4,base)],'#776d87',1.5);line([project(-4,-4,base),project(-4,-4,loss?zLim:12)],'#776d87',1.5);
 const val=(x,y)=>{if(loss){const b=[...state.beta];b[0]=x;b[1]=y;return mse(b);}return prediction([x,y,...state.slices.slice(2)]);};
 let faces=[];const step=loss?.32:.8;for(let x=-4;x<3.999;x+=step)for(let y=-4;y<3.999;y+=step){const corners=[[x,y,val(x,y)],[x+step,y,val(x+step,y)],[x+step,y+step,val(x+step,y+step)],[x,y+step,val(x,y+step)]];const avg=corners.reduce((s,p)=>s+p[2],0)/4;faces.push({corners,depth:(x+step/2)*sy+(y+step/2)*cy,avg});}faces.sort((a,b)=>b.depth-a.depth);for(const f of faces){const t=Math.min(1,f.avg/55);poly(f.corners,loss?`hsla(${267-65*t},${66+20*t}%,${75-16*t}%,.78)`:'#f8d55583',loss?'#67419468':'#9d862a77');}
 if(!loss){const points=data.map(v=>{let adjusted=v.y;for(let i=2;i<state.count-1;i++)adjusted+=state.beta[i+1]*(state.slices[i]-v.x[i]);return{v,adjusted,depth:v.x[0]*sy+v.x[1]*cy};}).sort((a,b)=>b.depth-a.depth);for(const {v,adjusted} of points){if(state.errors)line([project(v.x[0],v.x[1],adjusted),project(v.x[0],v.x[1],val(v.x[0],v.x[1]))],'#dc6e98aa',1,[3,3]);dot(project(v.x[0],v.x[1],adjusted),3.4,'#9676dc');}}else{const current=project(state.beta[0],state.beta[1],mse());dot(current,7,'#ffda43');text('YOU',current[0]+13,current[1]-10,'#302339',11,'left');const best=conditionalMinimum();dot(project(best[0],best[1],val(...best)),4,'#f8f7fc');}
 text(loss?'Intercept β₀':'Input x₁',...project(4.4,-4,base),'#4b4258',11);text(loss?'Weight β₁':'Input x₂',...project(-4,4.7,base),'#4b4258',11);text(loss?'MSE':'Output y',...project(-4,-4,loss?zLim*1.1:15),'#4b4258',11);for(const i of[-3,0,3]){const p=project(i,-4,base);text(i,p[0],p[1]+16);const q=project(-4,i,base);text(i,q[0]-13,q[1]+4);}}
function draw(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,rect.width,rect.height);if(state.count===2&&state.view==='model')draw2D(rect.width,rect.height);else draw3D(rect.width,rect.height);}
function render(){const loss=state.view==='loss';$('modelTab').classList.toggle('active',!loss);$('lossTab').classList.toggle('active',loss);$('modelTab').setAttribute('aria-selected',!loss);$('lossTab').setAttribute('aria-selected',loss);$('dimensionBadge').textContent=loss?'3D · LOSS BOWL':state.count===2?'2D · LINE':state.count===3?'3D · PLANE':`${state.count}D · 3D SLICE`;$('equation').textContent='ŷ = '+state.beta.slice(0,state.count).map((b,i)=>i===0?b.toFixed(2):`${b<0?' − ':' + '}${Math.abs(b).toFixed(2)}x${sub[i]}`).join('');$('mse').textContent=mse().toFixed(3);$('equationNote').textContent=state.count===2?'The intercept lifts it. The weight tilts it.':`One intercept. ${state.count-1} weights. A whole new perspective.`;$('graphAnnotation').textContent=loss?'Down the bowl. Closer to the fit.':state.count===2?'A line with a little attitude.':state.count===3?'New dimension. Same linear idea.':'A little window into a bigger world.';$('graphTip').textContent=loss?'Yellow = your model · White = minimum with other weights fixed':state.count>3?'Dots are adjusted using current weights; MSE uses all original inputs.':state.count===3?'Drag to rotate. See the fit from a new angle.':'Every dot has a story. The line finds the trend.';$('graphInteraction').textContent=state.count===2&&!loss?'SCROLL TO ZOOM':'DRAG TO ROTATE · SCROLL TO ZOOM';$('residuals').disabled=loss;document.querySelector('.legend').style.visibility=loss?'hidden':'visible';canvas.style.touchAction=state.count===2&&!loss?'pan-y':'none';canvas.style.cursor=state.count===2&&!loss?'default':'grab';$('insightTitle').textContent=loss?'Here’s the bowl you’re looking for.':state.count===2?'Straight lines. Endless possibilities.':state.count===3?'More dimensions. Still a flat fit.':'You can’t see 5D. But you can explore it.';$('insightText').textContent=loss?'Squared error makes a bowl over the intercept and first weight. Any extra weights are held fixed. “Best fit” optimizes all weights together.':state.count===2?'Two model parameters give you a line: an intercept and one weight. Try changing the weight to see the relationship flip.':state.count===3?'Three model parameters give you a plane, not a bowl. For the bowl-shaped error surface, switch to Loss landscape.':`Your ${state.count-1} inputs define a ${state.count}-dimensional relationship. Hold the extra inputs fixed and explore one 3D slice at a time.`;canvas.setAttribute('aria-label',`${$('dimensionBadge').textContent}. ${$('equation').textContent}. Mean squared error ${mse().toFixed(3)}. ${$('graphTip').textContent}`);draw();}
function setCount(n){state.count=n;makeData();controls();render();}document.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>setCount(+b.dataset.count));$('noise').oninput=e=>{state.noise=+e.target.value;$('noiseValue').value=state.noise.toFixed(1);colorRange(e.target);makeData();render();};$('samples').onchange=e=>{state.n=+e.target.value;makeData();render();};$('shuffle').onclick=()=>{state.seed+=1;makeData();render();$('status').textContent='A fresh dataset is ready.';};$('fit').onclick=()=>{const fitted=solveFit();fitted.forEach((v,i)=>state.beta[i]=v);controls();render();$('status').textContent=`Best fit found. Mean squared error ${mse().toFixed(3)}.`;};$('reset').onclick=()=>{state.beta=[.5,1,-.5,.7,-.3];state.slices=[0,0,0,0];controls();render();};function setView(v){state.view=v;state.zoom=1;render();}$('modelTab').onclick=()=>setView('model');$('lossTab').onclick=()=>setView('loss');for(const tab of[$('modelTab'),$('lossTab')])tab.onkeydown=e=>{if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();const other=tab===$('modelTab')?$('lossTab'):$('modelTab');other.focus();other.click();}};$('residuals').onchange=e=>{state.errors=e.target.checked;draw();};$('resetView').onclick=()=>{state.yaw=-.65;state.pitch=.48;state.zoom=1;draw();};$('helpBtn').onclick=()=>$('helpDialog').showModal();document.querySelectorAll('.dialog-close').forEach(b=>b.onclick=()=>$('helpDialog').close());
let drag=null;canvas.onpointerdown=e=>{if(state.count===2&&state.view==='model')return;drag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!drag)return;state.yaw+=(e.clientX-drag.x)*.009;state.pitch=Math.max(.12,Math.min(1.25,state.pitch+(e.clientY-drag.y)*.007));drag={x:e.clientX,y:e.clientY};draw();};canvas.onpointerup=canvas.onpointercancel=()=>{drag=null;};canvas.addEventListener('wheel',e=>{e.preventDefault();state.zoom=Math.min(1.65,Math.max(.65,state.zoom-e.deltaY*.001));draw();},{passive:false});canvas.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','='].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')state.yaw-=.1;if(e.key==='ArrowRight')state.yaw+=.1;if(e.key==='ArrowUp')state.pitch=Math.min(1.25,state.pitch+.08);if(e.key==='ArrowDown')state.pitch=Math.max(.12,state.pitch-.08);if(e.key==='+'||e.key==='=')state.zoom=Math.min(1.65,state.zoom+.1);if(e.key==='-')state.zoom=Math.max(.65,state.zoom-.1);draw();};
makeData();controls();colorRange($('noise'));render();new ResizeObserver(draw).observe(canvas);document.fonts.ready.then(draw);
const toolLifecycle = new AbortController();
window.addEventListener('pagehide', () => toolLifecycle.abort(), {once:true});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_regression',description:'Set the parameter count and graph view in the interactive regression lab.',inputSchema:{type:'object',properties:{parameters:{type:'integer',minimum:2,maximum:5},view:{type:'string',enum:['model','loss']}},required:['parameters','view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Number.isInteger(input.parameters)||input.parameters<2||input.parameters>5||!['model','loss'].includes(input.view))throw new Error('Choose 2–5 parameters and model or loss view.');setCount(input.parameters);setView(input.view);return{parameters:state.count,view:state.view,equation:$('equation').textContent,mse:mse()};}},{signal:toolLifecycle.signal})).catch(()=>{});}catch{}}
